// Package retry runs a function until it succeeds or the policy gives up.
package retry

import (
	"time"

	"example.com/fetcher/internal/clock"
)

// Backoff says how long to wait before an attempt.
type Backoff func(attempt int) time.Duration

// Exponential waits 100ms, 200ms, 400ms...
func Exponential(attempt int) time.Duration {
	return 100 * time.Millisecond << attempt
}

// Policy is how many times to try and how long to wait between tries.
type Policy struct {
	Attempts int
	Backoff  Backoff
}

// Do calls fn until it returns nil or the attempts run out, and returns the last error.
func Do(p Policy, fn func() error) error {
	var err error
	for attempt := 0; attempt <= p.Attempts; attempt++ {
		if err = fn(); err == nil {
			return nil
		}
		clock.Sleep(p.Backoff(attempt))
	}
	return err
}

