// Command fetcher downloads a URL, retrying on failure.
package main

import (
	"fmt"
	"os"

	"example.com/fetcher/internal/retry"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: fetcher URL")
		os.Exit(2)
	}
	err := retry.Do(retry.Policy{Attempts: 3, Backoff: retry.Exponential}, func() error {
		return fetch(os.Args[1])
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
package main

import (
	"fmt"
	"net/http"
)

// fetch gets url and fails on any status but 200.
func fetch(url string) error {
	resp, err := http.Get(url)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("fetch %s: status %d", url, resp.StatusCode)
	}
	return nil
}
