package retry

import (
	"errors"
	"slices"
	"testing"
	"time"

	"example.com/fetcher/internal/clock"
)

// fakeSleep records waits instead of sleeping, and restores clock.Sleep when the test ends.
func fakeSleep(t *testing.T) *[]time.Duration {
	t.Helper()
	var waits []time.Duration
	orig := clock.Sleep
	clock.Sleep = func(d time.Duration) { waits = append(waits, d) }
	t.Cleanup(func() { clock.Sleep = orig })
	return &waits
}

func TestDoAlwaysFailingTriesAttemptsTimesInTotal(t *testing.T) {
	waits := fakeSleep(t)
	fail := errors.New("fail")
	calls := 0

	err := Do(Policy{Attempts: 3, Backoff: Exponential}, func() error {
		calls++
		return fail
	})

	if !errors.Is(err, fail) {
		t.Errorf("err = %v, want %v", err, fail)
	}
	if calls != 3 {
		t.Errorf("calls = %d, want 3", calls)
	}
	// One wait before each new try, growing each time, and none after the last try.
	want := []time.Duration{100 * time.Millisecond, 200 * time.Millisecond}
	if !slices.Equal(*waits, want) {
		t.Errorf("waits = %v, want %v", *waits, want)
	}
}

func TestDoStopsOnSuccess(t *testing.T) {
	waits := fakeSleep(t)
	calls := 0

	err := Do(Policy{Attempts: 3, Backoff: Exponential}, func() error {
		calls++
		if calls < 2 {
			return errors.New("fail")
		}
		return nil
	})

	if err != nil {
		t.Errorf("err = %v, want nil", err)
	}
	if calls != 2 {
		t.Errorf("calls = %d, want 2", calls)
	}
	if want := []time.Duration{100 * time.Millisecond}; !slices.Equal(*waits, want) {
		t.Errorf("waits = %v, want %v", *waits, want)
	}
}

